}))()
"""

# 详情页读取：
# - textContent 为 DOM 文本节点中的原字符串（接口给的 CRLF/CR 应逐字符在内）；
# - innerText 为按 pre-wrap 实际渲染出的可见文本，分行必须与原稿行次一致，
#   既不挤成一行也不多出空行。
DETAIL_JS = r"""
(() => ({
  hash: location.hash,
  heading: (() => {
    const el = document.querySelector('h2');
    return el ? {text: el.textContent, visible: el.innerText} : null;
